items.referenceSolution:
#include <stdio.h>

void bumpFirst(int *p, int k) {
    *p = *p + k;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int bowl[10];
    int i;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &bowl[i]) != 1) {
            return 1;
        }
    }

    bumpFirst(bowl, 6);

    for (i = 0; i < n; i++) {
        printf("%d\n", bowl[i]);
    }
    return 0;
}

