items.referenceSolution:
#include <stdio.h>

void keepBigger(int *p, int v) {
    if (v > *p) {
        *p = v;
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int best = 0;
    int i;
    for (i = 0; i < n; i++) {
        int x;
        if (scanf("%d", &x) != 1) {
            return 1;
        }
        keepBigger(&best, x);
    }

    printf("%d\n", best);
    return 0;
}

